   137          //const int uid = ar_header.mid( 28, 6 ).trimmed().toInt();
   138          //const int gid = ar_header.mid( 34, 6 ).trimmed().toInt();
   139          const int mode = ar_header.mid(40, 8).trimmed().toInt();
   140          const qint64 size = ar_header.mid(48, 10).trimmed().toInt();
   141
   142          bool skip_entry = false; // Deal with special entries
   143          if (name.mid(0, 1) == "/") {
   144              if (name.mid(1, 1) == "/") { // Longfilename table entry
   145                  delete[] ar_longnames;
   146                  ar_longnames = new char[size + 1];
   147                  ar_longnames[size] = '\0';
   148                  dev->read(ar_longnames, size);
   149                  skip_entry = true;
   150                  //qCDebug(KArchiveLog) << "Read in longnames entry";
   151              } else if (name.mid(1, 1) == " ") { // Symbol table entry
   152                  //qCDebug(KArchiveLog) << "Skipped symbol entry";
   153                  dev->seek(dev->pos() + size);
   154                  skip_entry = true;
   155              } else { // Longfilename
